// web/scripts/sync-raid-preset.mjs
// data/curated/presets.json's "raid" preset, and sim/request/raid-consumes.json (that preset
// resolved per spec with the class kit, generated by `go run ./internal/genraidconsumes`) ->
// web/src/data/generated/raid-preset.json (buffs and debuffs) and raid-consumes.json (the
// per-spec rows, a chunk the page loads on demand to keep the islands inside their size
// budgets: src/lib/sim/preset-sets.ts), before dev, check, test and build. The BiS ranker, the tier list and every sim tool run their
// level-60 numbers under that preset (sim/request/preset.go). The /sim page's Raid-buffed
// preset reads its buff and debuff ids from here, so a number on the page is simmed with
// the buffs the published number was, and its consumables are each spec's published set
// (a rogue's poisons, a Survival hunter's ranged group), so the page's default figure is the
// published one. The file is gitignored like everything else under
// src/data/generated: it is derived, and a committed copy is a copy that goes stale.
//
// sim/request/published-presets.json (same generator) adds the ranker's rule for which
// preset each band publishes, written into raid-preset.json as `published` so the page's
// default preset is known before any chunk loads, and the bare preset per spec and level
// (the class kit) -> src/data/generated/bare-preset.json, the second on-demand chunk (owner
// ruling, round 6: below 60 the page defaults to the bare set the published number used).
//
// A missing or empty preset is fatal: a Raid-buffed preset with no buffs would still claim
// the label, and the page would sim a bare character under it without saying so. A spec
// with no consumables is fatal for the same reason.
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const webRoot = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = path.join(webRoot, '..');
const source = path.join(repoRoot, 'data', 'curated', 'presets.json');
const consumesSource = path.join(repoRoot, 'sim', 'request', 'raid-consumes.json');
const target = path.join(webRoot, 'src', 'data', 'generated', 'raid-preset.json');
const consumesTarget = path.join(webRoot, 'src', 'data', 'generated', 'raid-consumes.json');
const publishedSource = path.join(repoRoot, 'sim', 'request', 'published-presets.json');
const bareTarget = path.join(webRoot, 'src', 'data', 'generated', 'bare-preset.json');
const PUBLISHED_PRESETS = new Set(['bare', 'raid']);
const PRESET = 'raid';

/** The ids of one preset list, in the curated file's order. */
function idsOf(entries, list) {
  if (!Array.isArray(entries) || entries.length === 0) {
    throw new Error(`sync-raid-preset: ${source} preset "${PRESET}" has no ${list}`);
  }
  return entries.map((entry) => {
    if (typeof entry?.id !== 'string' || entry.id === '') {
      throw new Error(`sync-raid-preset: ${source} preset "${PRESET}" has a ${list} entry with no id`);
    }
    return entry.id;
  });
}

let curated;
try {
  curated = JSON.parse(await readFile(source, 'utf8'));
} catch (cause) {
  throw new Error(`sync-raid-preset: ${source} could not be read; data/curated owns the sim presets`, {
    cause,
  });
}
const preset = curated?.presets?.[PRESET];
if (preset === undefined) {
  throw new Error(`sync-raid-preset: ${source} has no "${PRESET}" preset`);
}

/** One spec's rows: each starts at a level (the first at 1) and names a non-empty id list. */
function validRows(spec, rows) {
  if (!isLevelRows(rows, (row) => isIdList(row.consumes) && row.consumes.length > 0)) {
    throw new Error(`sync-raid-preset: ${consumesSource} spec "${spec}" has no valid level rows`);
  }
  return rows;
}

/** Per spec, the raid set's consumable ids by level (the class kit's level gates). */
async function consumesBySpec() {
  let generated;
  try {
    generated = JSON.parse(await readFile(consumesSource, 'utf8'));
  } catch (cause) {
    throw new Error(
      `sync-raid-preset: ${consumesSource} could not be read; generate it with \`go run ./internal/genraidconsumes\` from sim/`,
      { cause },
    );
  }
  if (generated?.preset !== PRESET || typeof generated.specs !== 'object' || generated.specs === null) {
    throw new Error(`sync-raid-preset: ${consumesSource} is not the "${PRESET}" preset's consumables`);
  }
  const entries = Object.entries(generated.specs);
  if (entries.length === 0) throw new Error(`sync-raid-preset: ${consumesSource} names no spec`);
  return Object.fromEntries(entries.map(([spec, rows]) => [spec, validRows(spec, rows)]));
}

/** A list of ids, possibly empty (a bare kit can carry nothing). */
function isIdList(ids) {
  return Array.isArray(ids) && ids.every((id) => typeof id === 'string' && id !== '');
}

/** Rows that start at level 1 and rise, each passing `valid`. */
function isLevelRows(rows, valid) {
  return (
    Array.isArray(rows) &&
    rows.length > 0 &&
    rows[0]?.from_level === 1 &&
    rows.every(
      (row, index) =>
        Number.isInteger(row?.from_level) &&
        (index === 0 || row.from_level > rows[index - 1].from_level) &&
        valid(row),
    )
  );
}

/** Which preset each level publishes, and the bare set per spec and level. */
async function publishedPresets() {
  let generated;
  try {
    generated = JSON.parse(await readFile(publishedSource, 'utf8'));
  } catch (cause) {
    throw new Error(
      `sync-raid-preset: ${publishedSource} could not be read; generate it with \`go run ./internal/genraidconsumes\` from sim/`,
      { cause },
    );
  }
  if (!isLevelRows(generated?.published, (row) => PUBLISHED_PRESETS.has(row.preset))) {
    throw new Error(`sync-raid-preset: ${publishedSource} has no valid "published" rows`);
  }
  const bare = Object.entries(generated.bare ?? {});
  if (bare.length === 0) throw new Error(`sync-raid-preset: ${publishedSource} names no bare spec`);
  for (const [spec, rows] of bare) {
    if (!isLevelRows(rows, (row) => isIdList(row.buffs) && isIdList(row.consumes))) {
      throw new Error(`sync-raid-preset: ${publishedSource} bare spec "${spec}" has no valid level rows`);
    }
  }
  return { published: generated.published, bare: Object.fromEntries(bare) };
}

const { published, bare } = await publishedPresets();
const out = {
  buffs: idsOf(preset.buffs, 'buffs'),
  debuffs: idsOf(preset.debuffs, 'debuffs'),
  published,
};
const consumes = await consumesBySpec();
await mkdir(path.dirname(target), { recursive: true });
await writeFile(target, `${JSON.stringify(out, null, 2)}\n`, 'utf8');
await writeFile(consumesTarget, `${JSON.stringify(consumes)}\n`, 'utf8');
await writeFile(bareTarget, `${JSON.stringify(bare)}\n`, 'utf8');
console.log(
  `sync-raid-preset: ${out.buffs.length} buffs, ${out.debuffs.length} debuffs, ${Object.keys(consumes).length} specs' consumables -> ${path.relative(webRoot, target)}`,
);
